mapper.select:
SELECT CAST(p.id AS CHAR) id,p.code,p.barcode,p.name,CAST(p.category_id AS CHAR) category_id,c.name category_name,p.specification,p.unit,p.sale_price,p.image_path,COALESCE(b.qty,0) saleable_qty,(p.frozen_stocktake_id IS NOT NULL) frozen FROM product p JOIN category c ON c.id=p.category_id LEFT JOIN (SELECT i.product_id,SUM(i.stock_qty) qty FROM purchase_item i JOIN purchase_order o ON o.id=i.purchase_id WHERE o.status='IN_STOCK' AND i.batch_no IS NOT NULL AND i.stock_qty>0 AND (i.manages_expiry=0 OR i.expiry_date>=#{today}) GROUP BY i.product_id) b ON b.product_id=p.id WHERE p.enabled=1 AND p.can_sell=1
AND (CONVERT(p.code USING utf8mb4) LIKE CONCAT('%',#{query.keyword},'%') OR p.name LIKE CONCAT('%',#{query.keyword},'%') OR CONVERT(p.barcode USING utf8mb4)=#{query.keyword})
AND p.category_id=#{query.categoryId}AND p.enabled=#{query.enabled}AND p.manages_expiry=#{query.managesExpiry}AND p.can_purchase=#{query.canPurchase}AND p.can_sell=#{query.canSell}
ORDER BY p.created_at DESC,p.id DESC LIMIT #{query.pageSize} OFFSET #{query.offset}
